var (
	ftab  []string
	cetab = map[int]string{}
)

func init() {
	ftab = strings.Fields(ftabNames)
	for _, f := range strings.Fields(cetabNames) {
		i := strings.IndexByte(f, ':')
		n, _ := strconv.Atoi(f[:i])
		cetab[n] = f[i+1:]
	}
}

// funcName names a built-in function index; command equivalents have the
// fCeFunc bit (0x8000) set.
func funcName(idx int) string {
	if idx&0x8000 != 0 {
		if n, ok := cetab[idx&0x7FFF]; ok {
			return n
		}
		return "CE_" + strconv.Itoa(idx&0x7FFF)
	}
	if idx < len(ftab) && ftab[idx] != "_" {
		return ftab[idx]
	}
	return "FUNC_" + strconv.Itoa(idx)
}
